$('#partsSpeechBackBtn')?.addEventListener('click',()=>{audio.stopMusic();show('subjectScreen');});$('#partsSpeechHomeBtn')?.addEventListener('click',()=>{audio.stopMusic();updateHome();show('homeScreen');});$('#partsCourseStartBtn')?.addEventListener('click',()=>{const summary=partsCourseSummary(ensurePartsProgress()),part=summary.finished?PARTS_OF_SPEECH[0]:nextUnfinishedPart();selectedPartsLesson=part.id;startPartsLesson(part.id,{course:true});});$('#partsPracticeBtn')?.addEventListener('click',()=>startPartsLesson(selectedPart().id,{course:false}));$('#partsMixedBtn')?.addEventListener('click',startPartsMixed);$('#partsFinalChallengeBtn')?.addEventListener('click',startPartsMixed);
$$('[data-difficulty-profile]').forEach(b=>b.addEventListener('click',()=>{if(!pendingLaunch)return;const profile=b.dataset.difficultyProfile;prefs.lastDifficultyProfile=profile;save();const launch=pendingLaunch;pendingLaunch=null;startSession(launch.mode,launch.subject,{...launch.options,difficultyProfile:profile,returnScreen:pendingDifficultyReturn});}));$('.difficulty-back')?.addEventListener('click',()=>show(pendingDifficultyReturn||'subjectScreen'));
$$('.back-btn').forEach(b=>b.addEventListener('click',()=>{audio.stopMusic();updateHome();show('homeScreen');}));$('.subject-back').addEventListener('click',()=>show(pendingMode==='quiz'?'homeScreen':'activityScreen'));$$('.grade-card').forEach(b=>b.addEventListener('click',()=>{prefs.grade=Number(b.dataset.grade);save();updateHome();show('homeScreen');}));
function exportParentProgressPdf(){
  prefs.studentName=($('#parentStudentName')?.value||prefs.studentName||'').trim().slice(0,40);save();
  const grade=$('#parentProgressGrade')?.value||String(prefs.grade),rangeDays=$('#parentReportRange')?.value||'30';
  const report=buildProgressReport(prefs,{grade,rangeDays,studentName:prefs.studentName||'Student'});
  const result=saveProgressPdf(report);
  if(!result.native)showToast(`PDF downloaded: ${result.filename}`);else showToast('Saving PDF to Downloads...');
}
window.addEventListener('brainrotPdfSaved',e=>showToast(e.detail?.ok?'PDF saved to Downloads.':'Could not save the PDF. Please try again.'));
$('#exportProgressPdfBtn')?.addEventListener('click',exportParentProgressPdf);

$('#rematchBtn').addEventListener('click',()=>{if(game?.courseMeta?.kind==='parts'){const meta=game.courseMeta;if(meta.mixed)startPartsMixed();else startPartsLesson(meta.lessonId,{course:meta.course!==false});return;}startSession('battle',game.subject,{setting:game.setting,label:game.sessionLabel,difficultyProfile:game.difficultyProfile,returnScreen:game.returnScreen});});$('#resultContinueBtn')?.addEventListener('click',continuePartsCourseFromResult);$('#resultHomeBtn').addEventListener('click',()=>{audio.stopMusic();updateHome();show('homeScreen');});$('#quizRematchBtn').addEventListener('click',()=>startSession('quiz',game.subject,{difficultyProfile:game.difficultyProfile,returnScreen:game.returnScreen}));$('#quizHomeBtn').addEventListener('click',()=>{updateHome();show('homeScreen');});$('#reviewBtn').addEventListener('click',startReview);$('#practiceWeakSkillsBtn').addEventListener('click',startMasteryPractice);$('#reviewExitBtn').addEventListener('click',()=>show('quizResultScreen'));$('#reviewHomeBtn').addEventListener('click',()=>{updateHome();show('homeScreen');});$('#focusedRetakeBtn').addEventListener('click',startFocusedRetake);$('#saveSettingsBtn').addEventListener('click',saveSettings);$('#parentProgressGrade').addEventListener('change',renderParentDashboard);
function coreReturnLabel(){if(game?.mode==='quiz')return 'BACK TO QUIZZES';if(game?.returnScreen==='partsSpeechScreen')return 'BACK TO PARTS OF SPEECH';return game?.returnScreen==='subjectScreen'?'BACK TO CHALLENGES':'BACK TO ACTIVITIES';}
function openPauseOverlay({exitIntent=false,target=null}={}){if(document.body.dataset.screen!=='battleScreen'||!game)return;corePauseTarget=target||game.returnScreen||'activityScreen';paused=true;$('#pauseTitle').textContent=exitIntent?'LEAVE ACTIVITY?':'PAUSED';$('#pauseCopy').textContent=exitIntent?'Your current round will stop if you leave.':'Everything is frozen exactly where you left it.';$('#resumeBtn').textContent=exitIntent?'KEEP PLAYING':'RESUME';$('#quitToActivitiesBtn').textContent=coreReturnLabel();$('#pauseOverlay').classList.remove('hidden');audio.pause();}
function resumeCoreGame(){if(!game)return;paused=false;$('#pauseOverlay').classList.add('hidden');audio.resume();flushPausedDelays();}
function leaveCoreGame(destination='activityScreen'){paused=false;clearPausedDelays();$('#pauseOverlay').classList.add('hidden');audio.stopVoice();audio.stopMusic();game=null;if(destination==='homeScreen')updateHome();show(destination);}
function restartCoreRound(){if(!game)return;const old=game,options={setting:old.setting,label:old.sessionLabel,difficultyProfile:old.difficultyProfile,length:old.length,focusDescriptors:old.focusDescriptors,questionQueue:old.questionQueue,courseMeta:old.courseMeta,returnScreen:old.returnScreen};paused=false;clearPausedDelays();$('#pauseOverlay').classList.add('hidden');audio.stopVoice();audio.stopMusic();startSession(old.mode,old.subject,options);}
$('#answerContinueBtn').addEventListener('click',()=>{if(!game?.awaitingContinue||paused||document.body.dataset.screen!=='battleScreen')return;game.awaitingContinue=false;$('#answerContinueBtn').classList.add('hidden');game.index++;renderNext();});
$('#pauseBtn').addEventListener('click',()=>openPauseOverlay());$('#activityBackBtn')?.addEventListener('click',()=>openPauseOverlay({exitIntent:true,target:game?.returnScreen||'activityScreen'}));$('#activityHomeBtn')?.addEventListener('click',()=>openPauseOverlay({exitIntent:true,target:'homeScreen'}));$('#resumeBtn').addEventListener('click',resumeCoreGame);$('#restartRoundBtn')?.addEventListener('click',restartCoreRound);$('#quitToActivitiesBtn')?.addEventListener('click',()=>leaveCoreGame(corePauseTarget||game?.returnScreen||'activityScreen'));$('#quitBtn').addEventListener('click',()=>leaveCoreGame('homeScreen'));
window.addEventListener('brainrotAndroidBack',()=>{if(activeLogicScreen()){openLogicPause({leaveIntent:true,target:'logicHubScreen'});return;}if(document.body.dataset.screen==='logicHubScreen'){audio.stopMusic();show('activityScreen');return;}if(document.body.dataset.screen==='partsSpeechScreen'){audio.stopMusic();show('subjectScreen');return;}if(document.body.dataset.screen==='battleScreen'){openPauseOverlay({exitIntent:true,target:game?.returnScreen||'activityScreen'});return;}if(document.body.dataset.screen==='difficultyScreen'){show(pendingDifficultyReturn||'subjectScreen');return;}if(document.body.dataset.screen==='subjectScreen'){show(pendingMode==='quiz'?'homeScreen':'activityScreen');return;}if(document.body.dataset.screen!=='homeScreen'){updateHome();show('homeScreen');}});
$$('.btn,.icon-btn,.grade-card,.quick-tile,.status-card,.dock-item,.premium-chip').forEach(b=>b.addEventListener('pointerdown',()=>audio.sfx('tap',.28)));
document.addEventListener('visibilitychange',()=>{if(!document.hidden||paused)return;if(activeLogicScreen()){openLogicPause();return;}if(document.body.dataset.screen==='battleScreen'&&game)openPauseOverlay();});
window.addEventListener('resize',()=>{if(robotState&&document.body.dataset.screen==='robotLabScreen')updateRobotBoardState();});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
